import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, FormGroup, Label, Input } from 'reactstrap';

const SendPointsModal = ({ isOpen, toggle, headerId, loginUserId, otherUserId, onSendPoints }) => {
    const [amount, setAmount] = useState('');
    const [currentPoints, setCurrentPoints] = useState(0);
    const [sentPoints, setSentPoints] = useState(0);

    useEffect(() => {
        if (loginUserId) {
            fetch(`http://localhost:8080/api/users/${loginUserId}`)
                .then((response) => response.json())
                .then((data) => {
                    setCurrentPoints(data.points);
                })
                .catch((error) => console.error('Error:', error));
        }

        if (headerId) {
            fetch(`http://localhost:8080/api/chats/${headerId}/sentPoints`)
                .then((response) => response.json())
                .then((data) => {
                    setSentPoints(data.sent_points);
                })
                .catch((error) => console.error('Error:', error));
        }
    }, [headerId, loginUserId]);

    const handleSendPoints = () => {
        onSendPoints(amount);
        toggle();
    };

    return (
        <Modal isOpen={isOpen} toggle={toggle}>
            <ModalHeader toggle={toggle}>송금</ModalHeader>
            <ModalBody>
                <FormGroup>
                    <Label for="currentPoints">보유 포인트</Label>
                    <p>{currentPoints}</p>
                </FormGroup>
                <FormGroup>
                    <Label for="sentPoints">보낸 총 금액</Label>
                    <p>{sentPoints}</p>
                </FormGroup>
                <FormGroup>
                    <Label for="amount">송금할 금액</Label>
                    <Input type="number" id="amount" value={amount} onChange={(e) => setAmount(e.target.value)} />
                </FormGroup>
            </ModalBody>
            <ModalFooter>
                <Button color="primary" onClick={handleSendPoints}>
                    송금
                </Button>
                <Button color="secondary" onClick={toggle}>
                    취소
                </Button>
            </ModalFooter>
        </Modal>
    );
};

export default SendPointsModal;
